import cv2,numpy as np
F=np.load('source_pixels.npz')['rgb']
for dt in [1,2,4]:
 print('\\nDT',dt)
 for t in range(dt,96):
  d=np.max(abs(F[t].astype(np.int16)-F[t-dt].astype(np.int16)),2)
  m=(d>18).astype(np.uint8)*255
  m=cv2.morphologyEx(m,cv2.MORPH_CLOSE,np.ones((3,3),np.uint8));
  n,l,s,c=cv2.connectedComponentsWithStats(m)
  comps=[]
  for i in range(1,n):
   x,y,w,h,a=s[i]
   if a>12: comps.append((a,x,y,w,h))
  comps=sorted(comps,reverse=True)[:5]
  if t%2==0 or any(a>150 for a,*_ in comps): print(t,comps)
PY"
